 13#SP:// ===== UI 刷新回调（由 ui 层注册） =====
 14#RY:type RefreshCallback = () => void;
 15#YK:
 16#YK:const fullRefreshCallbacks: RefreshCallback[] = [];
 17#TV:const lightRefreshCallbacks: RefreshCallback[] = [];
 18#KS:const progressCallbacks: ((loaded: number, total: number) => void)[] = [];
