 49#BZ:  loadingCallbacks.forEach((cb) => cb(loading));
 50#ZY:}
 51#RK:
 52#NN:/** 文件变更延迟（设置应用时更新） */
 53#XN:let fileChangeDelay = 100;
 54#QK:export function setFileChangeDelay(v: number) {
 55#SQ:  fileChangeDelay = v;
 56#SP:}
 57#BR:export function getFileChangeDelay(): number {
 58#XP:  return fileChangeDelay;
 59#VQ:}
