 67#JH:// ===== 排序辅助 =====
 68#MX:function sortEntries(entries: DiaryEntry[]) {
 69#XP:  entries.sort((a, b) => {
 70#QP:    const dateCmp = b.date.localeCompare(a.date);
 71#MB:    return dateCmp !== 0 ? dateCmp : b.timeValue - a.timeValue;
 72#JV:  });
 73#HK:}
 74#NR:
 75#MQ:function assignIds(entries: DiaryEntry[]) {
 76#RP:  entries.forEach((entry, idx) => {
 77#RS:    if (!entry.id) {
 78#KW:      const safeTime = entry.time.replace(/:/g, '-');
 79#VS:      entry.id = `${entry.date}-${safeTime}-${idx}`;
 80#JH:    }
 81#XK:  });
 82#HK:}
