 84#QY:// ===== 加载 =====
 85#RW:
 86#ZK:/** 加载所有日记（分批并发）+ 影视 + 信 */
 87#YT:export async function loadAll() {
 88#SX:  if (state.data.isLoadingData) return;
 89#TN:  state.data.isLoadingData = true;
 90#JJ:  emitLoading(true);
 91#JS:  try {
 92#VQ:    const app = getApp();
 93#QQ:    const diaryDir = app.vault.getAbstractFileByPath(DIARY_DIRECTORY) as any;
 94#NX:    if (!diaryDir || !diaryDir.children) {
 95#YT:      state.data.originalDiaryEntries = [];
 96#KZ:      state.data.currentFilteredEntries = [];
 97#SH:      return;
 98#RZ:    }
 99#QQ:
100#SB:    const mdFiles = diaryDir.children
101#VB:      .filter((f: any) => f.extension === 'md')
102#JK:      .sort((a: any, b: any) => b.name.localeCompare(a.name));
103#WK:    const totalDiaryFiles = mdFiles.length;
104#MQ:
105#MQ:    let movieFiles: any[] = [];
106#XQ:    let letterFiles: any[] = [];
107#XB:
108#NS:    emitProgress(0, totalDiaryFiles || 1);
109#MQ:
110#HT:    const BATCH_CONCURRENCY = 10;
111#JJ:    const results: { date: string; entries: DiaryEntry[] }[] = [];
112#YJ:    if (totalDiaryFiles > 0) {
113#BN:      for (let i = 0; i < mdFiles.length; i += BATCH_CONCURRENCY) {
114#HJ:        const batch = mdFiles.slice(i, i + BATCH_CONCURRENCY);
115#VP:        const batchResults = await Promise.all(
116#MN:          batch.map(async (file: any, idx: number) => {
117#RK:            const content = await app.vault.read(file);
118#SR:            const entries = parseFile(content, file.basename);
119#VQ:            emitProgress(i + idx + 1, totalDiaryFiles);
120#VR:            return { date: file.basename, entries };
121#KV:          })
122#KS:        );
123#BW:        results.push(...batchResults);
124#QW:      }
125#TB:    }
126#SX:
127#QJ:    state.data.originalDiaryEntries = [];
128#WJ:    const map = new Map<string, DiaryEntry[]>();
129#VX:    for (const { date, entries } of results) {
130#YR:      if (entries.length) {
131#YR:        map.set(date, entries);
132#XH:        state.data.originalDiaryEntries.push(...entries.filter((e) => !isEncryptedEntry(e)));
133#MW:      }
134#KP:    }
135#HP:    setDiaryDataMap(map);
136#BM:
137#QM:    // ========== 加载影视文件 ==========
138#PM:    const movieDir = app.vault.getAbstractFileByPath(MOVIE_DIRECTORY) as any;
139#NM:    if (movieDir && movieDir.children) {
140#HP:      movieFiles = movieDir.children.filter((f: any) => f.extension === 'md');
141#SH:    }
142#HQ:
143#HY:    // ========== 加载信文件 ==========
144#RB:    const letterDir = app.vault.getAbstractFileByPath(LETTER_DIRECTORY) as any;
145#MQ:    if (letterDir && letterDir.children) {
146#PW:      letterFiles = letterDir.children.filter((f: any) => f.extension === 'md');
147#XZ:    }
148#HY:
149#PV:    const totalFiles = totalDiaryFiles + movieFiles.length + letterFiles.length;
150#YY:    if (totalFiles === 0) {
151#JM:      // 空库：渲染空态（原脚本此处早退导致空白面板，此处补齐刷新）
152#YN:      state.data.currentDisplayCount = 0;
153#TH:      emitFullRefresh();
154#YR:      emitProgress(0, 0);
155#ZK:      state.data.isLoadingData = false;
156#HZ:      emitLoading(false);
157#YM:      return;
158#RZ:    }
159#HZ:
160#RZ:    const loadedDiary = totalDiaryFiles;
161#RH:    emitProgress(loadedDiary, totalFiles);
162#KK:
163#BR:    for (let i = 0; i < movieFiles.length; i++) {
164#MS:      const movieEntry = await parseMovieFile(movieFiles[i]);
165#QR:      if (movieEntry) {
166#SM:        state.data.originalDiaryEntries.push(movieEntry);
167#TK:      }
168#WZ:      emitProgress(loadedDiary + i + 1, totalFiles);
169#XZ:    }
170#RK:
171#RK:    const offset = loadedDiary + movieFiles.length;
172#YQ:    for (let i = 0; i < letterFiles.length; i++) {
173#YW:      const letterEntry = await parseLetterFile(letterFiles[i]);
174#WQ:      if (letterEntry) {
175#XH:        state.data.originalDiaryEntries.push(letterEntry);
176#YT:      }
177#BX:      emitProgress(offset + i + 1, totalFiles);
178#MP:    }
179#WJ:
180#PX:    // 统一排序
181#QS:    sortEntries(state.data.originalDiaryEntries);
182#NK:    // 确保每个条目都有 id
183#JZ:    assignIds(state.data.originalDiaryEntries);
184#BR:
185#SZ:    // 修复点：使用 full refresh 正确应用筛选条件
186#MJ:    state.data.currentDisplayCount = 0;
187#TP:    emitFullRefresh();
188#QW:    emitProgress(0, 0); // 隐藏进度条（原 hideProgress）
189#BW:  } finally {
190#RP:    state.data.isLoadingData = false;
191#PQ:    emitLoading(false);
192#XN:  }
193#BQ:}
