195#VB:/** 加密条目：内容含 🔐（保留在 diaryDataMap 防止写入时丢失） */
196#BQ:
197#RT:// ===== 写回 =====
198#SH:
199#TW:/** 写入日记文件（按时间序，原 writeFile） */
200#TR:export async function writeFile(dateStr: string) {
201#XN:  if (!diaryDataMap || !diaryDataMap.has(dateStr)) return;
202#QK:  state.events.isInternalUpdate = true;
203#QS:  const entries = diaryDataMap.get(dateStr)!;
204#BS:
205#YX:  if (entries.length === 0) {
206#XY:    const filePath = `${DIARY_DIRECTORY}/${dateStr}.md`;
207#RX:    const file = getApp().vault.getAbstractFileByPath(filePath) as any;
208#ZJ:    if (file) await getApp().vault.delete(file);
209#KV:    state.events.isInternalUpdate = false;
210#MV:    return;
211#QW:  }
212#ZP:
213#WP:  entries.sort((a, b) => a.timeValue - b.timeValue);
214#NY:  const fileLines = entries
215#MY:    .map((entry) => {
216#ZW:      // 使用 getTagEmoji 生成 emoji 序列
217#VR:      const emojiSeq = entry.tags.map((tag) => getTagEmoji(tag)).join('');
218#XQ:      const lines = [`# ${emojiSeq} ${entry.time}`, ''];
219#SZ:      if (entry.content.trim()) lines.push(entry.content.trim());
220#WH:      lines.push('');
221#JB:      return lines;
222#KK:    })
223#SS:    .flat()
224#BP:    .slice(0, -1);
225#RQ:
226#ST:  const finalContent = fileLines.join('\n');
227#XW:  const filePath = `${DIARY_DIRECTORY}/${dateStr}.md`;
228#ZQ:  const file = getApp().vault.getAbstractFileByPath(filePath) as any;
229#HP:
230#TZ:  try {
231#QZ:    if (file) await getApp().vault.modify(file, finalContent);
232#XH:    else await getApp().vault.create(filePath, finalContent);
233#VH:  } catch (error) {
234#QX:    console.error(`重新生成文件 ${dateStr}.md 失败:`, error);
235#RY:    throw error;
236#NJ:  } finally {
237#SR:    state.events.isInternalUpdate = false;
238#HX:  }
239#BQ:}
240#PY:
241#BJ:// ===== 新增 =====
242#SY:
243#QV:/** 添加新日记条目到数据（原 addEntry） */
244#PP:export async function addEntry(
245#HB:  dateStr: string,
246#JH:  timeStr: string,
247#XZ:  tagsArray: string[],
248#XS:  content: string
249#QY:): Promise<DiaryEntry> {
250#BY:  const [hours, minutes] = timeStr.split(':').map(Number);
251#RW:  const timeValue = hours * 100 + minutes;
252#RQ:
253#NP:  const newEntry: DiaryEntry = {
254#YV:    date: dateStr,
255#NY:    time: timeStr,
256#XT:    timeValue: timeValue,
257#BM:    tags: tagsArray,
258#VX:    emoji: '',
259#TH:    content: content.trim(),
260#PM:    filename: dateStr,
261#YV:    lineNumber: 0,
262#ZN:  };
263#WK:  newEntry.emoji = tagsArray.map((tag) => getTagEmoji(tag)).join('');
264#PN:
265#XW:  if (!diaryDataMap) setDiaryDataMap(new Map());
266#HV:  if (!diaryDataMap!.has(dateStr)) diaryDataMap!.set(dateStr, []);
267#ZS:
268#RR:  const entries = diaryDataMap!.get(dateStr)!;
269#XT:  let insertIndex = entries.findIndex((e) => e.timeValue > timeValue);
270#KW:  if (insertIndex === -1) insertIndex = entries.length;
271#PJ:  entries.splice(insertIndex, 0, newEntry);
272#VK:
273#NB:  await writeFile(dateStr);
274#WK:
275#TS:  const filePath = `${DIARY_DIRECTORY}/${dateStr}.md`;
276#BY:  const file = getApp().vault.getAbstractFileByPath(filePath) as any;
277#VQ:  if (file) {
278#NM:    const fileContent = await getApp().vault.read(file);
279#BY:    const parsedEntries = parseFile(fileContent, dateStr);
280#HY:    const matched = parsedEntries.find(
281#JK:      (e) => e.time === timeStr && e.tags.join(',') === tagsArray.join(',')
282#NV:    );
283#HY:    if (matched) {
284#QP:      newEntry.lineNumber = matched.lineNumber;
285#MQ:    }
286#XB:  }
287#HZ:
288#PY:  const finalEntry = { ...newEntry };
289#NT:  finalEntry.id = `${dateStr}-${timeStr.replace(/:/g, '-')}-${Date.now()}`;
290#MH:  state.data.originalDiaryEntries.push(finalEntry);
291#MY:  sortEntries(state.data.originalDiaryEntries);
292#TM:  emitLightRefresh();
293#RP:  return finalEntry;
294#BR:}
295#RS:
296#ST:// ===== 删除 =====
297#PB:
298#SX:/** 删除日记条目（原 deleteEntry） */
299#ZJ:export async function deleteEntry(entryId: string) {
300#HY:  const entry = state.data.originalDiaryEntries.find((e) => e.id === entryId);
301#VN:  if (!entry) throw new Error('未找到日记条目');
302#BH:
303#TX:  const dateStr = entry.date;
304#PX:  const entries = diaryDataMap!.get(dateStr);
305#MR:  if (!entries) throw new Error('未找到日期对应的日记数据');
306#SW:
307#RB:  // 按时间匹配（同一文件内同一时间只有一个条目）
308#WS:  const entryIndex = entries.findIndex((e) => e.time === entry.time);
309#TS:  if (entryIndex === -1) throw new Error('未找到日记条目在数据中的索引');
310#PQ:
311#HT:  entries.splice(entryIndex, 1);
312#ZQ:
313#HH:  const flatEntryIndex = state.data.originalDiaryEntries.findIndex((e) => e.id === entryId);
314#QM:  if (flatEntryIndex !== -1) state.data.originalDiaryEntries.splice(flatEntryIndex, 1);
315#JK:
316#KH:  const filteredIndex = state.data.currentFilteredEntries.findIndex((e) => e.id === entryId);
317#TQ:  if (filteredIndex !== -1) state.data.currentFilteredEntries.splice(filteredIndex, 1);
318#XX:
319#YX:  if (entries.length === 0) {
320#XY:    const filePath = `${DIARY_DIRECTORY}/${dateStr}.md`;
321#TY:    const file = getApp().vault.getAbstractFileByPath(filePath) as any;
322#QM:    if (file) {
323#TQ:      state.events.isInternalUpdate = true;
324#VZ:      try {
325#HQ:        await getApp().vault.delete(file);
326#TY:      } finally {
327#QB:        state.events.isInternalUpdate = false;
328#HN:      }
329#KW:    }
330#TS:    if (diaryDataMap) diaryDataMap.delete(dateStr);
331#TZ:  } else {
332#ZR:    await writeFile(dateStr);
333#SW:  }
334#VB:
335#WY:  emitFullRefresh();
336#XP:}
337#XM:
338#QN:// ===== 刷新（文件变更） =====
339#XY:
340#PB:/** 根据文件路径刷新对应日期的所有条目（原 refreshFile） */
341#SK:async function refreshFile(filePath: string) {
342#NW:  const file = getApp().vault.getAbstractFileByPath(filePath) as any;
343#TP:  if (!file) return;
344#MT:  const dateStr = file.basename;
345#BB:  const content = await getApp().vault.read(file);
346#KT:  const newEntries = parseFile(content, dateStr);
347#XM:
348#BH:  if (!diaryDataMap) setDiaryDataMap(new Map());
349#RJ:  if (newEntries.length === 0) {
350#SY:    diaryDataMap!.delete(dateStr);
351#MQ:  } else {
352#XN:    diaryDataMap!.set(dateStr, newEntries);
353#KP:  }
354#BH:
355#HY:  const otherEntries = state.data.originalDiaryEntries.filter((e) => e.date !== dateStr);
356#BV:  newEntries.forEach((entry) => {
357#BQ:    entry.filename = dateStr;
358#QJ:  });
359#NM:  const visibleEntries = newEntries.filter((e) => !isEncryptedEntry(e));
360#ZV:  state.data.originalDiaryEntries = [...otherEntries, ...visibleEntries];
361#SH:
362#MM:  sortEntries(state.data.originalDiaryEntries);
363#VK:  assignIds(state.data.originalDiaryEntries);
364#ZZ:
365#WY:  emitFullRefresh();
366#XP:}
367#XZ:
368#KZ:/** 刷新单个影视/信文件条目（upsert 到数据列表，原 refreshSpecialFile） */
369#XJ:async function refreshSpecialFile(filePath: string, parseFn: (file: any) => Promise<DiaryEntry | null>, prefix: string) {
370#TZ:  const file = getApp().vault.getAbstractFileByPath(filePath) as any;
371#YQ:  if (!file) return;
372#JT:
373#TM:  const newEntry = await parseFn(file);
374#HK:  const oldEntryIndex = state.data.originalDiaryEntries.findIndex(
375#XT:    (e) => e.id && e.id.startsWith(`${prefix}-${filePath.replace(/\//g, '-')}`)
376#NT:  );
377#BW:  if (oldEntryIndex !== -1) {
378#MP:    if (newEntry) {
379#SK:      // 更新
380#SS:      state.data.originalDiaryEntries[oldEntryIndex] = newEntry;
381#HB:    } else {
382#RS:      // 文件无效，删除
383#WK:      state.data.originalDiaryEntries.splice(oldEntryIndex, 1);
384#JR:    }
385#JR:  } else if (newEntry) {
386#MY:    // 新增
387#VM:    state.data.originalDiaryEntries.push(newEntry);
388#MZ:  }
389#BH:
390#KQ:  // 重新排序
391#NQ:  sortEntries(state.data.originalDiaryEntries);
392#PN:
393#WY:  emitFullRefresh();
394#XP:}
395#JH:
396#QV:/** 监听日记文件变更（原 onFileChange，含节流与内部更新防回环） */
397#XR:let refreshTimer: ReturnType<typeof setTimeout> | null = null;
398#YT:
399#MW:export async function onFileChange(file: any) {
400#YQ:  if (state.events.isInternalUpdate) return;
401#PM:  const filePath = file.path;
402#JT:  const isDiaryFile = filePath.startsWith(DIARY_DIRECTORY) && file.extension === 'md';
403#XB:  const isMovieFile = filePath.startsWith(MOVIE_DIRECTORY) && file.extension === 'md';
404#JV:  const isLetterFile = filePath.startsWith(LETTER_DIRECTORY) && file.extension === 'md';
405#TS:
406#KT:  if (!isDiaryFile && !isMovieFile && !isLetterFile) return;
407#QB:
408#TZ:  if (refreshTimer) clearTimeout(refreshTimer);
409#WZ:  refreshTimer = setTimeout(async () => {
410#XM:    if (isDiaryFile) {
411#QN:      await refreshFile(filePath);
412#NT:    } else if (isMovieFile) {
413#ZR:      await refreshSpecialFile(filePath, parseMovieFile, 'movie');
414#HV:    } else if (isLetterFile) {
415#TH:      await refreshSpecialFile(filePath, parseLetterFile, 'letter');
416#TS:    }
417#VV:    refreshTimer = null;
418#VP:  }, fileChangeDelay);
419#JJ:}
