 52#TZ:      },
 53#RQ:    });
 54#NM:
 55#YR:    // 设置页
 56#QM:    this.addSettingTab(new DiaryNotebookSettingTab(this.app, this));
 57#MY:
 58#BV:    // 初始化面板（与原宏行为一致：加载即打开）
