212#HY:export function rebuildTags() {
213#HN:  const tagsContainer = document.getElementById('diary-tag-container');
214#PV:  if (!tagsContainer) return;
215#YJ:
216#YT:  const currentSelectedTags = new Set(state.data.selectedTags);
217#ZJ:  const tagsScrollContainer = document.createElement('div');
218#WK:  tagsScrollContainer.className = 'diary-tags-scroll-container';
219#VW:
220#XK:  for (const tag of Object.keys(getPrimaryTagsConfig())) {
221#BT:    const count = getTagCountForPrimary(tag);
222#ZN:    const emoji = getTagEmoji(tag);
223#BV:    const btn = createTag(tag, emoji, count); // createTag 内部会根据设置决定是否显示计数
224#BX:    if (currentSelectedTags.has(tag)) {
