238#TY:// 辅助函数：统计主标签自身 + 所有二级标签的总条目数
239#HK:function getTagCountForPrimary(primaryTag: string) {
240#ZK:  let count = 0;
241#KJ:  const subTags = getSubTagsOfPrimary(primaryTag);
242#TB:  for (const entry of state.data.originalDiaryEntries) {
243#VM:    if (entry.tags.includes(primaryTag)) {
244#RS:      count++;
245#ZR:    } else if (subTags) {
246#XP:      if (entry.tags.some((t) => subTags.some((sub) => sub.tag === t))) {
247#VP:        count++;
248#HQ:      }
249#JP:    }
250#JJ:  }
251#RJ:  return count;
252#MQ:}
