254#JP:// 创建单个标签按钮
255#SJ:export function createTag(tag: string, emoji: string, count: number | null) {
256#BX:  const showCount = getShowTagCountSetting(); // 默认 true
257#VM:
258#ZZ:  const button = document.createElement('button');
259#NT:  button.className = 'diary-tag-btn';
260#XZ:  button.dataset.tag = tag;
261#MR:
262#SM:  let countHtml = '';
263#XK:  if (showCount && count !== null && count !== undefined) {
264#BV:    countHtml = `<span style="margin-left:4px; font-size:10px; opacity:0.8;">(${count})</span>`;
265#YT:  }
266#YW:  button.innerHTML = `${emoji} ${tag} ${countHtml}`;
267#MK:  button.style.cssText =
268#MB:    'border-radius:10px;background:var(--background-secondary);cursor:pointer;font-size:10px;color:var(--text-normal);transition:all 0.2s;display:flex;align-items:center;flex-shrink:0;box-shadow:none;';
269#ZJ:
270#BM:  const subTags = getSubTagsOfPrimary(tag);
271#BJ:  if (subTags && subTags.length > 0) {
272#HV:    button.style.border = '1px solid var(--background-modifier-hover)';
273#VV:    button.style.padding = '0 8px';
274#YT:  }
275#ZK:
276#HW:  button.onmouseenter = () => !state.data.selectedTags.has(tag) && (button.style.backgroundColor = 'var(--background-modifier-hover)');
277#VX:  button.onmouseleave = () => !state.data.selectedTags.has(tag) && (button.style.backgroundColor = 'var(--background-secondary)');
278#NB:
279#ZQ:  button.onclick = (e) => {
280#NP:    e.stopPropagation();
281#QS:    if (!state.data.selectedTags.has(tag)) {
282#NP:      state.data.selectedTags.clear();
283#ZJ:      state.data.selectedTags.add(tag);
284#NK:      document.querySelectorAll('.diary-tag-btn').forEach((btn) => {
285#VW:        (btn as HTMLElement).style.background = 'var(--background-secondary)';
286#VY:        (btn as HTMLElement).style.color = 'var(--text-normal)';
287#XW:      });
288#ZT:      button.style.background = 'var(--interactive-accent)';
289#QV:      button.style.color = 'var(--background-primary)';
290#WB:    } else {
291#QT:      state.data.selectedTags.delete(tag);
292#MY:      button.style.background = 'var(--background-secondary)';
293#SN:      button.style.color = 'var(--text-normal)';
294#XP:    }
295#YR:    applyFilter({ skipTagCountUpdate: true });
296#TZ:  };
297#QR:
298#TV:  return button;
299#YS:}
