333#RB:
334#BW:export function setLoadingState(loading: boolean) {
335#PN:  const searchBtn = document.querySelector('.diary-popup-header button[title="搜索日记"]') as HTMLButtonElement | null;
336#ZR:  const searchContainer = document.getElementById('diary-search-container');
337#RZ:  const searchInput = document.getElementById('diary-search-input') as HTMLInputElement | null;
338#YY:
339#KQ:  if (searchBtn) {
340#ZY:    searchBtn.disabled = loading;
341#RR:    searchBtn.style.opacity = loading ? '0.5' : '1';
342#MX:    searchBtn.style.pointerEvents = loading ? 'none' : 'auto';
343#ZJ:  }
344#SQ:
345#SX:  if (loading) {
346#QY:    if (searchContainer && searchContainer.style.display !== 'none') {
347#BZ:      searchContainer.style.display = 'none';
348#JN:    }
349#VR:    if (searchInput) {
350#HY:      searchInput.value = '';
351#BS:    }
352#JY:    if (state.data.searchDebounceTimer) clearTimeout(state.data.searchDebounceTimer);
353#SS:    state.data.currentSearchKeyword = '';
