445#RK:
446#QM:function registerEscapeListener() {
447#MW:  diaryEscHandle = escManager.register('diary', {
448#JB:    isVisible: () => {
449#ZQ:      const byId = (id: string) => document.getElementById(id);
450#ZT:      const dt = byId('unified-datetime-picker-mask');
451#ZR:      if (dt && dt.isConnected) return true;
452#WP:      const conf = byId('delete-confirm-mask');
453#RJ:      if (conf && conf.style.display === 'block') return true;
454#PR:      const tag = byId('diary-tag-selector-mask');
455#XB:      if (tag && tag.style.display === 'block') return true;
456#SS:      const add = byId('add-diary-mask');
457#RH:      if (add && add.style.display === 'block') return true;
458#TX:      const date = byId('diary-date-filter-mask');
459#BB:      if (date && date.style.display === 'block') return true;
460#RT:      const main = byId('diary-filter-mask');
461#JB:      return main ? main.style.visibility === 'visible' : false;
462#XM:    },
463#SK:    close: () => {
464#JV:      const byId = (id: string) => document.getElementById(id);
465#WR:      const conf = byId('delete-confirm-mask');
466#VV:      if (conf && conf.style.display === 'block') {
467#ZJ:        conf.style.display = 'none';
468#YM:        return;
469#HP:      }
470#BV:      const tag = byId('diary-tag-selector-mask');
471#NR:      if (tag && tag.style.display === 'block') {
472#ZT:        tag.style.display = 'none';
473#XT:        return;
474#PR:      }
475#QZ:      const add = byId('add-diary-mask');
476#HY:      if (add && add.style.display === 'block') {
477#ST:        add.style.display = 'none';
478#RZ:        const ap = byId('add-diary-popup');
479#XM:        if (ap) ap.style.display = 'none';
480#ST:        return;
481#HM:      }
482#TW:      const date = byId('diary-date-filter-mask');
483#RQ:      if (date && date.style.display === 'block') {
484#RK:        date.style.display = 'none';
485#XM:        return;
486#XH:      }
487#SZ:      const main = byId('diary-filter-mask');
488#XH:      if (main && main.style.visibility === 'visible') {
489#YP:        main.style.visibility = 'hidden';
490#SR:        const popup = byId('diary-tag-filter');
491#MS:        if (popup) popup.style.visibility = 'hidden';
492#YQ:      }
493#TX:    },
494#TK:  });
495#HK:}
