 18#WS:// ===== 进度条（原 202-237） =====
 19#NW:
 20#JZ:function ensureProgressBar(): HTMLElement | null {
 21#TY:  const tagContainer = document.getElementById('diary-tag-container');
 22#MQ:  if (!tagContainer) return null;
 23#KW:  let progressBar = tagContainer.querySelector('.diary-github-progress-bar') as HTMLElement | null;
 24#ZS:  if (!progressBar) {
 25#TK:    progressBar = document.createElement('div');
 26#TK:    progressBar.className = 'diary-github-progress-bar';
 27#TT:    tagContainer.insertBefore(progressBar, tagContainer.querySelector('.diary-tags-scroll-container'));
 28#WV:  }
 29#ZH:  progressBar.style.width = '0%';
 30#VN:  progressBar.style.opacity = '1';
 31#RN:  progressBar.style.height = '2px';
 32#MR:  return progressBar;
 33#QP:}
 34#SM:
 35#XR:function updateProgress(loadedCount: number, totalCount: number) {
 36#JV:  const bar = ensureProgressBar();
 37#VN:  if (!bar) return;
 38#HQ:  if (totalCount === 0) {
 39#SN:    bar.style.opacity = '0';
 40#QP:    return;
 41#WT:  }
 42#VH:  const percent = (loadedCount / totalCount) * 100;
 43#NH:  bar.style.width = `${percent}%`;
 44#MY:  if (loadedCount >= totalCount) {
 45#NZ:    bar.style.opacity = '0';
 46#TJ:  }
 47#BQ:}
 48#MY:
 49#SV:function hideProgress() {
 50#JX:  const bar = document.querySelector('.diary-github-progress-bar') as HTMLElement | null;
 51#KW:  if (bar) bar.style.opacity = '0';
 52#HJ:}
