 56#JJ:export function createMaskAndPopup() {
 57#MJ:  const existingMask = document.getElementById('diary-filter-mask');
 58#HX:  const existingPopup = document.getElementById('diary-tag-filter');
 59#WQ:  if (existingMask) existingMask.remove();
 60#SR:  if (existingPopup) existingPopup.remove();
 61#JM:
 62#BN:  state.ui.maskLayer = document.createElement('div');
 63#QX:  state.ui.maskLayer.id = 'diary-filter-mask';
 64#TV:  state.ui.maskLayer.style.cssText =
 65#VM:    'position:fixed;top:0;left:0;right:0;bottom:0;background:var(--background-modifier-cover);z-index:9998;visibility:hidden;';
 66#XP:  state.ui.maskLayer.onclick = () => {
