 73#MW:  state.ui.tagFilterPopup.style.cssText =
 74#YQ:    'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:var(--background-primary);border-radius:12px;box-shadow:0 10px 40px rgba(0,0,0,0.2);z-index:9999;width:90%;max-width:800px;max-height:80vh;display:flex;flex-direction:column;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,system-ui,sans-serif;visibility:hidden;';
 75#VY:
 76#ZP:  const header = createHeader();
 77#KB:  const tagsContainer = createTagBar();
 78#WR:  state.ui.entriesContainer = document.createElement('div');
 79#KH:  state.ui.entriesContainer.id = '__diary-entries-container__';
 80#HK:  state.ui.entriesContainer.style.cssText = 'flex:1;overflow-y:auto;padding:0;position:relative;min-height:300px;';
 81#PK:
 82#KZ:  const searchContainer = document.createElement('div');
 83#PT:  searchContainer.id = 'diary-search-container';
 84#QX:  searchContainer.style.cssText = 'padding: 0 24px 12px 24px;';
 85#KP:
 86#KY:  const searchInput = document.createElement('input');
 87#TQ:  searchInput.id = 'diary-search-input';
 88#TW:  searchInput.type = 'text';
 89#YP:  searchInput.placeholder = '🔍 搜索日记（正文、类型、时间）...';
 90#QB:  searchInput.style.cssText = `
 91#TH:  width: 100%;
 92#TS:  padding: 10px 12px;
 93#ZK:  font-size: 14px;
 94#HJ:  border: 1px solid var(--background-modifier-border);
 95#ZY:  border-radius: 8px;
 96#QY:  background: var(--background-primary);
 97#MB:  color: var(--text-normal);
 98#BK:  outline: none;
 99#WV:  box-sizing: border-box;
100#HS:`;
101#BP:  searchInput.addEventListener('input', (e) => {
102#SM:    const keyword = (e.target as HTMLInputElement).value.trim();
103#RT:    if (state.data.searchDebounceTimer) clearTimeout(state.data.searchDebounceTimer);
104#SW:    state.data.searchDebounceTimer = setTimeout(() => {
105#XW:      state.data.currentSearchKeyword = keyword;
106#XR:      applyFilter();
107#JW:    }, 300);
108#VM:  });
109#RB:  searchContainer.appendChild(searchInput);
110#WW:
111#YB:  state.ui.tagFilterPopup.appendChild(header);
112#QZ:  state.ui.tagFilterPopup.appendChild(tagsContainer);
113#PB:  state.ui.tagFilterPopup.appendChild(searchContainer);
114#BQ:  state.ui.tagFilterPopup.appendChild(state.ui.entriesContainer);
115#QM:
116#PZ:  // 创建二级标签区域容器（初始隐藏）
117#PN:  const subTagsContainer = document.createElement('div');
118#JZ:  subTagsContainer.id = 'diary-subtags-container';
119#NB:  subTagsContainer.style.cssText = 'padding: 0 24px 12px 24px; display: none; flex-wrap: wrap; gap: 8px;  margin-top: 12px;';
120#ZR:
121#VM:  // 插入到 diary-tag-container 之后，search-container 之前
122#PS:  const tagContainer = document.getElementById('diary-tag-container');
123#NJ:  if (tagContainer && tagContainer.parentNode) {
124#JW:    tagContainer.insertAdjacentElement('afterend', subTagsContainer);
125#MN:  } else {
126#QV:    // 降级：直接添加到 popup
127#JN:    state.ui.tagFilterPopup.insertBefore(subTagsContainer, searchContainer);
128#KB:  }
129#KY:
130#RN:  document.body.appendChild(state.ui.maskLayer);
131#NV:  document.body.appendChild(state.ui.tagFilterPopup);
132#WR:  createTagPicker();
133#PX:}
