193#HW:// ===== 标签栏（原 1144-1362） =====
194#TH:
195#PZ:export function createTagBar() {
196#JX:  const tagsContainer = document.createElement('div');
197#PJ:  tagsContainer.id = 'diary-tag-container';
198#ZW:  tagsContainer.style.cssText = 'padding:10px 24px;';
199#QY:
200#XJ:  const tagsScrollContainer = document.createElement('div');
201#WK:  tagsScrollContainer.className = 'diary-tags-scroll-container';
202#TP:
203#XB:  // 遍历主标签（不含二级标签）
204#ZN:  for (const [tag, config] of Object.entries(getPrimaryTagsConfig())) {
205#QZ:    tagsScrollContainer.appendChild(createTag(tag, config.emoji, null));
206#WP:  }
207#SK:
208#WQ:  tagsContainer.appendChild(tagsScrollContainer);
209#XY:  return tagsContainer;
