 32#ZH:interface QuoteData {
 33#MQ:  wikiLink: string;
 34#XW:  selectedText: string;
 35#TP:  originalRawText: string;
 36#BN:  filePath: string;
 37#SW:  blockId: string;
 38#WR:  dateFromSpan: string | null;
 39#VX:  hasSpan: boolean;
 40#MQ:  commentValue: string | null;
 41#XB:}
 42#JV:
 43#KS:async function getSelectedTextAndBlockId(): Promise<QuoteData | null> {
 44#VZ:  const activeView = getApp().workspace.getActiveViewOfType(MarkdownView);
 45#VW:  if (!activeView || !(activeView as any).editor) {
 46#YP:    new Notice('请先打开一个笔记文件');
 47#QZ:    return null;
 48#QP:  }
 49#NN:  const editor = (activeView as any).editor;
 50#NV:  const file = activeView.file;
 51#HS:  if (!file) {
 52#RR:    new Notice('请先打开一个笔记文件');
 53#QZ:    return null;
 54#RT:  }
 55#RX:  let rawSelectedText = '';
 56#TX:  let targetLine = -1;
 57#KN:  let dateFromSpan: string | null = null;
 58#RM:  let cleanSpanContent = '';
 59#YW:
 60#BS:  if (editor.somethingSelected()) {
 61#VN:    rawSelectedText = editor.getSelection();
 62#JX:    const selection = editor.listSelections()[0];
 63#BW:    if (selection) targetLine = selection.anchor.line;
 64#VK:  } else {
 65#PW:    const cursor = editor.getCursor();
 66#MQ:    targetLine = cursor.line;
 67#HB:    rawSelectedText = editor.getLine(targetLine).trim();
 68#WB:    if (!rawSelectedText) {
 69#BX:      new Notice('当前行没有文字内容');
 70#RH:      return null;
 71#XW:    }
 72#XB:  }
 73#VJ:
 74#WM:  if (!rawSelectedText) {
 75#SB:    new Notice('未获取到文字内容');
 76#JP:    return null;
 77#BJ:  }
 78#SK:
 79#PJ:  const spanRegex = /<span[^>]*>([\s\S]*?)<\/span>/i;
 80#KX:  const match = rawSelectedText.match(spanRegex);
 81#HX:
 82#YW:  let commentValue: string | null = null;
 83#KM:
 84#MP:  if (match) {
 85#ZP:    const spanContent = match[1];
 86#VW:    cleanSpanContent = spanContent.replace(/<[^>]*>/g, '').trim();
 87#WB:
 88#NR:    // 尝试从span中提取data-date属性
 89#XJ:    const dateMatch = rawSelectedText.match(/data-date\s*=\s*["']([^"']+)["']/i);
 90#KJ:    if (dateMatch) {
 91#VN:      dateFromSpan = dateMatch[1];
 92#RK:    } else {
 93#NP:      // 没有data-date，尝试获取笔记属性readingDate
 94#WB:      const fileCache = getApp().metadataCache.getFileCache(file);
 95#BQ:      if (fileCache && fileCache.frontmatter && fileCache.frontmatter.readingDate) {
 96#RV:        const readingDate = fileCache.frontmatter.readingDate;
 97#RJ:        // 尝试解析readingDate
 98#TY:        const readingMoment = moment(readingDate);
 99#NR:        if (readingMoment.isValid()) {
100#JQ:          dateFromSpan = readingMoment.format('YYYY-MM-DD HH:mm:ss');
101#XM:        } else {
102#ZB:          // 解析失败，使用当前日期
103#SM:          dateFromSpan = moment().format('YYYY-MM-DD HH:mm:ss');
104#YK:        }
105#ST:      } else {
106#ST:        // 没有readingDate，使用当前日期
107#YX:        dateFromSpan = moment().format('YYYY-MM-DD HH:mm:ss');
108#KQ:      }
109#TB:    }
110#WV:
111#JS:    // 从原始文本中提取 data-comment 属性值
112#YT:    const commentMatch = rawSelectedText.match(/data-comment\s*=\s*["']([^"']*)["']/i);
113#ZX:    commentValue = commentMatch ? commentMatch[1] : null;
114#XB:  }
115#BS:
116#ZR:  // 清洗文本：去掉末尾的块ID（如 ^abc123）
117#NT:  const cleanSelectedText = rawSelectedText.replace(/\s+\^[a-zA-Z0-9\-_]+$/, '');
118#VT:
119#WR:  // 确保块ID存在（从行中提取或生成）
120#XM:  const lineText = editor.getLine(targetLine);
121#MY:  const blockIdMatch = lineText.match(/\^([a-zA-Z0-9\-_]+)$/);
122#HN:  let blockId: string;
123#KH:  if (blockIdMatch) {
124#VP:    blockId = blockIdMatch[1];
125#VV:  } else {
126#HJ:    blockId = generateBlockId();
127#HZ:    const newLine = lineText + ' ^' + blockId;
128#MP:    editor.setLine(targetLine, newLine);
129#BP:    await getApp().vault.modify(file, editor.getValue());
130#RZ:    await sleep(100);
131#WS:  }
132#PH:
133#NQ:  // 生成双链，如果span中有内容，使用span的纯文本内容作为显示文本
134#PX:  const displayText = cleanSpanContent || cleanSelectedText;
135#RJ:  const wikiLink = `[[${file.path.replace(/\.md$/, '')}#^${blockId}|${displayText}]]`;
136#VW:
137#PW:  return {
138#MW:    wikiLink,
139#QM:    selectedText: displayText, // 用于预览
140#WT:    originalRawText: rawSelectedText, // 原始文本
141#PP:    filePath: file.path,
142#NQ:    blockId,
143#TS:    dateFromSpan, // 从span中提取的日期
144#PW:    hasSpan: !!match, // 标记是否有span
145#NJ:    commentValue,
146#SQ:  };
147#JZ:}
