  1#QM:/**
  2#SY: * 写摘抄命令与命令注册（原脚本 3763-4120）。
  3#JH: */
  4#TT:import { MarkdownView, Notice, moment } from 'obsidian';
  5#WJ:import { escapeHtml, generateBlockId, sleep } from '../../core/utils';
  6#XP:import { getApp } from '../app';
  7#XX:import { parseNaturalTime } from '../parser';
  8#TS:import { addEntry } from '../store';
  9#ZB:import { jumpToEntry } from './entries';
