221#BB:function createQuoteSaveHandler(popup: HTMLElement, mask: HTMLElement, quoteData: QuoteData, q: any) {
222#BS:  return async function () {
223#WQ:    const datetimeInput = document.getElementById('add-diary-datetime') as HTMLInputElement | null;
224#KV:    if (!datetimeInput) {
225#KB:      new Notice('无法获取日期时间');
226#SV:      return;
227#RZ:    }
228#SX:
229#XR:    if (!quoteData.wikiLink || quoteData.wikiLink.trim() === '') {
230#KN:      new Notice('摘抄内容为空，无法保存');
231#ZJ:      return;
232#RZ:    }
233#TS:
234#JZ:    // 读取用户选择的多个标签
235#XQ:    const typeContainer = document.getElementById('add-diary-type-container')!;
236#HH:    const selTagNames: string[] = [];
237#XM:    typeContainer.querySelectorAll('.diary-tag-selector-btn.diary-active').forEach((btn) => {
238#MR:      selTagNames.push((btn as HTMLElement).dataset.tag!);
239#RM:    });
240#YZ:    if (selTagNames.length === 0) {
241#XJ:      new Notice('请至少选择一个标签');
242#YT:      return;
243#RZ:    }
244#NK:
245#RV:    // 日期时间处理
246#WQ:    const userInput = datetimeInput.value.trim();
247#TW:    let targetMoment = parseNaturalTime(userInput);
248#KP:    if (!targetMoment || !targetMoment.isValid()) {
249#HB:      targetMoment = moment(userInput, 'YYYY-MM-DD HH:mm', true);
250#SQ:      if (!targetMoment.isValid()) {
251#XN:        new Notice('日期时间格式不正确');
252#TV:        return;
253#ZV:      }
254#TB:    }
255#MH:
256#ZY:    const dateStr = targetMoment.format('YYYY-MM-DD');
257#QN:    const timeStr = targetMoment.format('HH:mm');
258#TX:
259#ZQ:    try {
260#WP:      // 构建最终内容
261#SN:      let finalContent = quoteData.wikiLink;
262#SH:      if (quoteData.commentValue) {
263#PM:        finalContent += quoteData.commentValue;
264#XX:      }
265#PQ:      if (quoteData.filePath && quoteData.filePath.startsWith('书库/')) {
266#ZJ:        const fileName = quoteData.filePath.split('/').pop()!.replace(/\.md$/, '');
267#JX:        finalContent += `\n\n#《${fileName}》`;
268#HP:      }
269#NT:
270#PB:      const newEntry = await addEntry(dateStr, timeStr, selTagNames, finalContent);
271#HH:      if (!newEntry) throw new Error('addEntry 返回空');
272#VN:      new Notice('摘抄已保存');
273#ZS:      mask.style.display = 'none';
274#ZH:      popup.style.display = 'none';
275#MS:      cleanupDialogOverrides(popup, mask, q);
276#KR:      await jumpToEntry(newEntry, 'edit');
277#YK:    } catch (error: any) {
278#VS:      console.error('保存摘抄失败:', error);
279#KJ:      new Notice('保存摘抄失败: ' + error.message);
280#ZQ:    }
281#RK:  };
282#JZ:}
