  1#VP:/**
  2#TN: * 筛选联动共享逻辑（applyFilter 与标签栏重建共用，避免 entries ↔ panel 循环依赖）。
  3#JS: * 原脚本 updateTitleSuffix（1934）、refreshSubTagsBar（1208）、updateSubTagsCounts（1312）、updateTagCounts（914）。
  4#HN: */
  5#NH:import { getPrimaryTagsConfig, getParentPrimaryTag, getSubTagsOfPrimary, getTagEmoji, isSubTag } from '../config';
  6#BR:import { getCurrentActiveParentForSub, setCurrentActiveParentForSub, state } from '../state';
  7#YT:import { getShowTagCountSetting } from './panel';
  8#QB:
  9#RQ:/** 更新标题上的日期后缀（原 1934-1952） */
 10#QH:export function updateTitleSuffix() {
 11#QV:  const titleElement = document.querySelector('#diary-tag-filter .diary-popup-header h3');
 12#WM:  if (!titleElement) return;
 13#PB:
 14#TH:  const existingSuffix = titleElement.querySelector('.date-filter-suffix');
 15#ZY:  if (existingSuffix) existingSuffix.remove();
 16#HS:
 17#JK:  if (state.data.currentDateFilter) {
 18#SX:    const suffixSpan = document.createElement('span');
 19#JS:    suffixSpan.className = 'date-filter-suffix';
 20#QT:    suffixSpan.style.cssText = 'margin-left: 8px; font-size: 14px; font-weight: normal; color: var(--text-muted);';
 21#MH:    if (state.data.currentDateFilter.month) {
 22#QN:      suffixSpan.textContent = `${state.data.currentDateFilter.year}-${state.data.currentDateFilter.month}`;
 23#RN:    } else {
 24#WV:      suffixSpan.textContent = state.data.currentDateFilter.year;
 25#HQ:    }
 26#QJ:    titleElement.appendChild(suffixSpan);
 27#RT:  }
 28#BQ:}
 29#RV:
 30#YQ:/** 刷新二级标签区域（根据选中的主标签或二级标签，原 1208-1309） */
 31#SW:export function refreshSubTagsBar() {
 32#SR:  const subContainer = document.getElementById('diary-subtags-container');
 33#PW:  if (!subContainer) return;
 34#JH:
 35#BS:  // 寻找需要显示二级标签的父标签：
 36#JW:  // 1. 如果有选中的主标签且包含二级标签，使用它
 37#BK:  // 2. 否则如果有选中的二级标签，使用它的父标签
 38#PM:  let activeParent: string | null = null;
 39#JH:  for (const tag of state.data.selectedTags) {
 40#MK:    const subTags = getSubTagsOfPrimary(tag);
 41#ZZ:    if (subTags && subTags.length > 0) {
 42#TW:      activeParent = tag;
 43#YX:      break;
 44#RM:    }
 45#QZ:  }
 46#WJ:  if (!activeParent) {
 47#YX:    for (const tag of state.data.selectedTags) {
 48#QZ:      if (isSubTag(tag)) {
 49#YV:        activeParent = getParentPrimaryTag(tag);
 50#ZQ:        break;
 51#VP:      }
 52#JP:    }
 53#XB:  }
 54#QW:
 55#JT:  setCurrentActiveParentForSub(activeParent);
 56#YY:
 57#KM:  if (!activeParent) {
 58#SB:    subContainer.style.display = 'none';
 59#KX:    subContainer.innerHTML = '';
 60#NB:    return;
 61#QW:  }
 62#KX:
 63#MH:  subContainer.style.display = 'flex';
 64#TM:  subContainer.innerHTML = '';
 65#MT:
 66#RH:  const subTags = getSubTagsOfPrimary(activeParent);
 67#TB:  if (!subTags) return;
 68#ZV:
 69#XR:  // 基于原始数据统计二级标签出现次数
 70#ZR:  const countMap = new Map<string, number>();
 71#YP:  state.data.originalDiaryEntries.forEach((entry) => {
 72#YM:    entry.tags.forEach((tag) => {
