 38#MT:
 39#WS:export function applyFilter(options: { skipTagCountUpdate?: boolean } = {}) {
 40#KK:  const { skipTagCountUpdate = false } = options;
 41#WQ:  let filtered = [...state.data.originalDiaryEntries];
 42#VW:
 43#SV:  // 多标签筛选：对于每个选中的标签，如果是主标签且有二级标签，则匹配该主标签或其任意二级标签
 44#PZ:  if (state.data.selectedTags.size > 0) {
 45#RR:    filtered = filtered.filter((entry) => {
 46#QP:      // 遍历选中的标签，只要满足一个即可
 47#YX:      for (const tag of state.data.selectedTags) {
 48#SY:        // 检查是否是主标签且有二级标签
 49#WT:        const subTags = getSubTagsOfPrimary(tag);
 50#TV:        if (subTags && subTags.length > 0) {
 51#XW:          // 主标签条件：entry包含该主标签，或者包含任意一个二级标签
 52#MJ:          if (entry.tags.includes(tag) || entry.tags.some((t) => subTags.some((sub) => sub.tag === t))) {
 53#QQ:            return true;
 54#VH:          }
 55#HV:        } else {
 56#JB:          // 普通主标签或二级标签：直接匹配
 57#WP:          if (entry.tags.includes(tag)) {
 58#XR:            return true;
 59#BM:          }
 60#SN:        }
 61#RR:      }
 62#RN:      return false;
 63#XT:    });
 64#PM:  }
 65#ZY:
 66#KN:  // 日期筛选
 67#HS:  if (state.data.currentDateFilter) {
 68#WQ:    filtered = filtered.filter((entry) => {
 69#VB:      const [year, month] = entry.date.split('-');
 70#SW:      if (state.data.currentDateFilter!.month) {
 71#KN:        return year === state.data.currentDateFilter!.year && month === state.data.currentDateFilter!.month;
 72#HW:      }
 73#RH:      return year === state.data.currentDateFilter!.year;
 74#TY:    });
 75#PM:  }
 76#MB:
 77#JJ:  // 搜索筛选
 78#TK:  if (state.data.currentSearchKeyword) {
 79#QR:    const lowerKeyword = state.data.currentSearchKeyword.toLowerCase();
 80#QZ:    filtered = filtered.filter((entry) => {
 81#TS:      return (
 82#WT:        entry.content.toLowerCase().includes(lowerKeyword) ||
 83#NH:        entry.tags.some((tag) => tag.toLowerCase().includes(lowerKeyword)) ||
 84#HH:        entry.time.toLowerCase().includes(lowerKeyword) ||
 85#JS:        entry.date.includes(state.data.currentSearchKeyword)
 86#HH:      );
 87#MM:    });
 88#PM:  }
 89#TY:
 90#MH:  // 更新显示用的单标签标志
 91#MX:  state.ui.singleSelectedTagForDisplay = state.data.selectedTags.size === 1 ? [...state.data.selectedTags][0] : null;
 92#PK:
 93#WK:  state.data.currentFilteredEntries = filtered;
 94#HM:  state.data.currentDisplayCount = 0;
 95#WX:  if (state.ui.entriesContainer) {
 96#RS:    state.ui.entriesContainer.innerHTML = '';
 97#HB:    state.ui.scrollContainer = null;
 98#SW:  }
 99#HB:  renderEntries();
100#TX:  updateTitleSuffix();
101#SS:  refreshSubTagsBar();
102#ZY:
103#QQ:  if (!skipTagCountUpdate) {
104#MW:    updateTagCounts();
105#TW:  }
106#BQ:}
