486#HV:export function initScroll() {
487#VV:  if (!state.ui.entriesContainer)
488#YM:    state.ui.entriesContainer = document.getElementById('__diary-entries-container__');
489#KT:  state.ui.entriesContainer!.addEventListener('scroll', () => {
490#KB:    if (state.data.isLoadingMore) return;
491#MP:    const scrollTop = state.ui.entriesContainer!.scrollTop;
492#MW:    const scrollHeight = state.ui.entriesContainer!.scrollHeight;
493#WQ:    const clientHeight = state.ui.entriesContainer!.clientHeight;
494#YN:    if (scrollTop + clientHeight >= scrollHeight - 50) {
495#SR:      state.data.isLoadingMore = true;
496#VM:      renderEntries();
497#VX:    }
498#NV:    updateSticky();
499#MZ:  });
