503#RY:export function updateSticky() {
504#QV:  if (!state.ui.entriesContainer || !state.ui.scrollContainer) return;
505#YB:  const dateSeparators = state.ui.scrollContainer.querySelectorAll('.diary-date-separator');
506#ZB:  if (dateSeparators.length === 0) return;
507#BJ:  const containerRect = state.ui.entriesContainer.getBoundingClientRect();
508#JH:  const scrollTop = state.ui.entriesContainer.scrollTop;
509#RZ:  let currentStickyDate: HTMLElement | null = null;
510#JK:  for (let i = dateSeparators.length - 1; i >= 0; i--) {
511#MP:    const separator = dateSeparators[i] as HTMLElement;
512#JT:    const separatorRect = separator.getBoundingClientRect();
513#SK:    const separatorTop = separatorRect.top - containerRect.top + scrollTop;
514#WR:    if (separatorTop <= scrollTop + 5) {
515#YX:      currentStickyDate = separator;
516#QP:      break;
517#RM:    }
518#RK:  }
519#YB:  dateSeparators.forEach((separator) => {
520#MP:    const el = separator as HTMLElement;
521#VV:    el.style.position = 'sticky';
522#XW:    el.style.top = '0';
523#TJ:    el.style.zIndex = '10';
524#HP:    el.style.background = 'var(--background-primary)';
525#HW:  });
526#KP:  if (currentStickyDate) currentStickyDate.style.zIndex = '20';
527#SV:}
