  1#KP:/**
  2#TV: * 条目列表：筛选、渲染、卡片交互、滚动、编辑、删除确认。
  3#ZS: * 原脚本 1865-2578 行。
  4#XS: */
  5#XB:import { Component, MarkdownRenderer, Notice } from 'obsidian';
  6#YM:import { confirm } from '../../core/confirm';
  7#WB:import { getApp } from '../app';
  8#BH:import { BATCH_SIZE, DIARY_DIRECTORY, LONG_PRESS_DURATION, MOVIE_DIRECTORY, getSubTagsOfPrimary, getTagEmoji } from '../config';
  9#XY:import { deleteEntry, getIsProcessingRemainingFiles } from '../store';
 10#YX:import { state } from '../state';
 11#QX:import type { DateFilter, DiaryEntry } from '../types';
 12#NW:import { getEnableLongPressSetting } from './panel';
 13#VV:import { showTagPicker } from './dialogs';
 14#HT:import { refreshSubTagsBar, updateTagCounts, updateTitleSuffix } from './filter-shared';
