 16#HP:// ===== 渲染 markdown（原 3531-3548） =====
 17#ZX:
 18#PJ:export async function renderMarkdown(content: string, container: HTMLElement, filePath: string | null) {
 19#NX:  if (!content) {
 20#JR:    container.innerHTML = '';
 21#YT:    return;
 22#MM:  }
 23#ZN:  container.innerHTML = '';
 24#YQ:  // 如果没有文件路径，或者文件不存在，直接使用 innerHTML 渲染 HTML 标签
 25#NW:  if (!filePath) {
 26#JN:    container.innerHTML = content;
 27#XN:    return;
 28#NQ:  }
 29#VV:  const file = getApp().vault.getAbstractFileByPath(filePath) as any;
 30#XK:  if (!file) {
 31#JZ:    container.innerHTML = content;
 32#XN:    return;
 33#KB:  }
 34#VV:  await MarkdownRenderer.render(getApp(), content, container, file.path, new Component());
 35#XH:}
 36#QT:
 37#QW:// ===== 筛选（原 1867-1952） =====
 38#MT:
 39#WS:export function applyFilter(options: { skipTagCountUpdate?: boolean } = {}) {
 40#KK:  const { skipTagCountUpdate = false } = options;
 41#WQ:  let filtered = [...state.data.originalDiaryEntries];
 42#VW:
 43#SV:  // 多标签筛选：对于每个选中的标签，如果是主标签且有二级标签，则匹配该主标签或其任意二级标签
 44#PZ:  if (state.data.selectedTags.size > 0) {
 45#RR:    filtered = filtered.filter((entry) => {
 46#QP:      // 遍历选中的标签，只要满足一个即可
 47#YX:      for (const tag of state.data.selectedTags) {
 48#SY:        // 检查是否是主标签且有二级标签
 49#WT:        const subTags = getSubTagsOfPrimary(tag);
 50#TV:        if (subTags && subTags.length > 0) {
 51#XW:          // 主标签条件：entry包含该主标签，或者包含任意一个二级标签
