303#BJ:export function addLongPress(element: HTMLElement, type: 'content' | 'emoji', entryId: string) {
304#NV:  if (!getEnableLongPressSetting()) return; // 禁用长按
305#HK:
306#VS:  let pressTimer: ReturnType<typeof setTimeout> | null = null;
307#BY:  let isLongPress = false;
308#YH:  let touchStartX = 0;
309#RJ:  let touchStartY = 0;
310#VS:  const MOVE_THRESHOLD = 10;
311#NH:
312#BS:  // 使用全局 LONG_PRESS_DURATION（已从设置读取）
313#PH:  const duration = LONG_PRESS_DURATION;
314#TX:
315#KK:  const longPressHandler = () => {
316#PW:    if (type === 'content') {
317#NN:      copyLink(entryId);
318#SB:    } else if (type === 'emoji') {
319#VQ:      showTagPicker(entryId);
320#ZH:    }
321#MR:  };
322#WK:
323#RK:  element.addEventListener(
324#ZT:    'touchstart',
325#TY:    (e) => {
326#NZ:      if (state.ui.editingEntryId === entryId) return;
327#YW:      const touch = e.touches[0];
328#TY:      touchStartX = touch.clientX;
329#WS:      touchStartY = touch.clientY;
330#HK:      isLongPress = false;
331#JM:      pressTimer = setTimeout(() => {
332#BP:        isLongPress = true;
333#PR:        longPressHandler();
334#VY:      }, duration);
335#VP:    },
336#BQ:    { passive: true }
337#ZR:  );
338#BM:
339#SN:  element.addEventListener(
340#NW:    'touchmove',
341#BB:    (e) => {
342#XH:      if (!pressTimer) return;
343#YR:      const touch = e.touches[0];
344#VV:      const deltaX = Math.abs(touch.clientX - touchStartX);
345#HW:      const deltaY = Math.abs(touch.clientY - touchStartY);
346#YS:      if (deltaX > MOVE_THRESHOLD || deltaY > MOVE_THRESHOLD) {
347#ZZ:        clearTimeout(pressTimer);
348#SY:        pressTimer = null;
349#JH:      }
350#WS:    },
351#BQ:    { passive: true }
352#ZR:  );
353#XN:
354#MH:  element.addEventListener('touchend', (e) => {
355#KV:    if (pressTimer) clearTimeout(pressTimer);
356#YN:    if (isLongPress) {
357#XV:      e.preventDefault();
358#KJ:      isLongPress = false;
359#XP:    }
360#VW:  });
361#QB:
362#YX:  element.addEventListener('mousedown', (e) => {
363#JJ:    if (state.ui.editingEntryId === entryId) return;
364#RX:    pressTimer = setTimeout(longPressHandler, duration);
365#VW:  });
366#XS:
367#YJ:  element.addEventListener('mouseup', () => { if (pressTimer) clearTimeout(pressTimer); });
368#BS:  element.addEventListener('mouseleave', () => { if (pressTimer) clearTimeout(pressTimer); });
369#HB:}
