512#JT:    const separatorRect = separator.getBoundingClientRect();
513#SK:    const separatorTop = separatorRect.top - containerRect.top + scrollTop;
514#WR:    if (separatorTop <= scrollTop + 5) {
515#YX:      currentStickyDate = separator;
516#QP:      break;
517#RM:    }
518#RK:  }
519#YB:  dateSeparators.forEach((separator) => {
520#MP:    const el = separator as HTMLElement;
521#VV:    el.style.position = 'sticky';
522#XW:    el.style.top = '0';
523#TJ:    el.style.zIndex = '10';
524#HP:    el.style.background = 'var(--background-primary)';
525#HW:  });
526#KP:  if (currentStickyDate) currentStickyDate.style.zIndex = '20';
527#SV:}
528#QV:
529#NP:export function fixMobileSelect(element: HTMLElement) {
530#NH:  if (!state.ui.isTouchDevice) return;
531#YQ:  element.addEventListener(
532#QQ:    'touchstart',
533#KB:    function mobileCursorFix(e) {
534#JY:      if (document.activeElement !== this) {
535#MN:        (this as HTMLElement).focus();
536#YP:        setTimeout(() => {
537#HH:          if (window.getSelection && window.getSelection()!.rangeCount === 0) {
538#JV:            const range = document.createRange();
539#QQ:            range.selectNodeContents(this as HTMLElement);
540#NK:            range.collapse(false);
541#QH:            const selection = window.getSelection()!;
542#NP:            selection.removeAllRanges();
543#NS:            selection.addRange(range);
544#HZ:          }
545#HT:        }, 50);
546#YJ:      }
547#WS:    },
548#BQ:    { passive: true }
549#JZ:  );
550#YN:  element.addEventListener(
551#NR:    'touchmove',
552#PY:    function preventScroll(e) {
553#VP:      if (state.ui.editingEntryId) e.stopPropagation();
554#PR:    },
555#BX:    { passive: false }
556#ZV:  );
557#XW:}

