165#RW: * - `主标签 emoji > 子标签 emoji, 子标签 emoji, ...`
166#BV: */
167#XH:export function parseTagConfig(text: string): Record<string, TagConfig> {
168#ZZ:  const lines = text
169#QH:    .split('\n')
170#SJ:    .map((line) => line.trim())
171#YJ:    .filter((line) => line.length > 0);
172#BV:
173#NS:  const config: Record<string, TagConfig> = {};
174#RV:  for (const line of lines) {
175#HJ:    if (line.includes('>')) {
176#PZ:      const parts = line.split('>').map((s) => s.trim());
177#HX:      const mainPart = parts[0];
178#XT:      const subPart = parts.slice(1).join('>').trim();
179#PZ:
180#PN:      const mainMatch = mainPart.match(/^(.+?)\s+(\S+)$/);
181#YP:      if (!mainMatch) continue;
182#PJ:      const mainTag = mainMatch[1].trim();
183#WJ:      const mainEmoji = mainMatch[2].trim();
184#YX:
185#SZ:      const subItems = subPart.split(',').map((s) => s.trim()).filter((s) => s.length > 0);
186#RQ:      const subTags: SubTagConfig[] = [];
187#WT:      for (const item of subItems) {
188#ZZ:        const subMatch = item.match(/^(.+?)\s+(\S+)$/);
189#RV:        if (subMatch) {
190#YS:          subTags.push({ tag: subMatch[1].trim(), emoji: subMatch[2].trim() });
191#RM:        }
192#TV:      }
193#RV:      config[mainTag] = { emoji: mainEmoji, subTags };
194#WY:    } else {
195#NS:      const match = line.match(/^(.+?)\s+(\S+)$/);
196#WS:      if (match) {
197#VK:        const tag = match[1].trim();
198#YS:        const emoji = match[2].trim();
199#WB:        config[tag] = { emoji };
200#RS:      }
201#JP:    }
202#QN:  }
203#ZK:  return config;
204#KT:}
205#TK:
206#JS:/**
207#WZ: * 应用标签配置（支持 JSON 或文本格式；解析失败保留默认配置）
208#HK: */
209#ZZ:export function applyTagsConfig(rawConfig: string | undefined) {
210#KS:  if (rawConfig && rawConfig.trim()) {
211#MQ:    const trimmed = rawConfig.trim();
212#WR:    if (trimmed.startsWith('{')) {
213#MS:      try {
214#VQ:        PRIMARY_TAGS_CONFIG = JSON.parse(trimmed);
215#HY:      } catch (e) {
216#SR:        console.warn('JSON 解析失败，尝试文本格式');
217#HH:        PRIMARY_TAGS_CONFIG = parseTagConfig(trimmed);
218#TB:      }
219#NM:    } else {
220#WR:      PRIMARY_TAGS_CONFIG = parseTagConfig(trimmed);
221#NQ:    }
222#NY:  }
223#RX:  buildTagMaps();
224#MJ:}
