226#ZX:// ===== 排序辅助 =====
227#ZV:
228#BY:/**
229#JK: * 获取写日记弹窗中标签的排序列表：
230#XQ: * 有二级标签的主标签隐藏，只显示其二级标签（按配置顺序）
231#QX: */
232#KY:export function getSortedTagsForAddDialog(): string[] {
233#BY:  const result: string[] = [];
234#ZB:  for (const [primary, config] of Object.entries(PRIMARY_TAGS_CONFIG)) {
235#KQ:    if (config.subTags && config.subTags.length > 0) {
236#HV:      for (const sub of config.subTags) {
237#KW:        result.push(sub.tag);
238#WV:      }
239#ZV:    } else {
240#BK:      result.push(primary);
241#NM:    }
242#QK:  }
243#PB:  return result;
244#ZK:}
