 17#BS: */
 18#PP:export function parseFile(content: string, dateStr: string): DiaryEntry[] {
 19#MY:  const entries: DiaryEntry[] = [];
 20#KQ:  const lines = content.split('\n');
 21#TZ:  let currentEntry: DiaryEntry | null = null;
 22#RH:  let contentLines: string[] = [];
 23#VK:
 24#PN:  const headingRegex = /^#\s*((?:\S+)+)\s+(\d{2}:\d{2})/u;
 25#NY:
 26#WZ:  for (let i = 0; i < lines.length; i++) {
 27#XY:    const line = lines[i];
 28#PX:    const headingMatch = line.match(headingRegex);
 29#MV:
 30#RQ:    if (headingMatch) {
 31#WZ:      if (currentEntry) {
 32#XH:        currentEntry.content = contentLines.join('\n').trim();
 33#RR:        entries.push(currentEntry);
 34#HR:        contentLines = [];
 35#TP:      }
 36#BY:
 37#ZV:      const emojiSequence = headingMatch[1];
 38#BN:      const time = headingMatch[2];
 39#JW:
 40#MQ:      const [hours, minutes] = time.split(':').map(Number);
 41#RH:      if (isNaN(hours) || hours < 0 || hours > 23 || minutes < 0 || minutes > 59) continue;
 42#MX:
 43#HW:      const timeValue = hours * 100 + minutes;
 44#NV:
 45#RJ:      // 使用 emoji 映射解析每个 emoji 对应的标签
 46#SK:      const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
 47#SZ:      const segments = segmenter.segment(emojiSequence);
 48#TP:      const tags: string[] = [];
 49#YT:      for (const seg of segments) {
 50#XB:        const ch = seg.segment;
 51#WW:        const mappedTag = emojiToTagMap[ch];
 52#RM:        if (mappedTag) {
 53#XP:          tags.push(mappedTag);
 54#WV:        }
 55#KY:      }
 56#JN:      if (tags.length === 0) {
 57#MB:        tags.push('日记');
 58#WX:      }
 59#PB:
 60#TJ:      currentEntry = {
 61#KP:        date: dateStr,
 62#SN:        time: time,
 63#YH:        timeValue: timeValue,
 64#YN:        tags: tags,
 65#BM:        emoji: emojiSequence,
 66#TR:        content: '',
 67#RR:        filename: dateStr,
 68#SP:        lineNumber: i + 1,
 69#MZ:      };
 70#BT:    } else if (currentEntry) {
 71#HN:      if (line.trim() === '' && i + 1 < lines.length && lines[i + 1].match(/^#\s/)) {
 72#TH:        currentEntry.content = contentLines.join('\n').trim();
 73#HJ:        entries.push(currentEntry);
 74#YW:        currentEntry = null;
 75#XZ:        contentLines = [];
 76#RN:      } else {
 77#TQ:        contentLines.push(line);
 78#VB:      }
 79#JP:    }
 80#XB:  }
 81#KS:
 82#JK:  if (currentEntry) {
 83#QN:    currentEntry.content = contentLines.join('\n').trim();
 84#YZ:    entries.push(currentEntry);
 85#KN:  }
 86#HS:
 87#WQ:  // 向后兼容旧数据
 88#MT:  for (const entry of entries) {
 89#JB:    if ((entry as any).type !== undefined) {
 90#MJ:      entry.tags = [(entry as any).type];
 91#MJ:      delete (entry as any).type;
 92#NN:    }
 93#ZH:    if (!entry.tags || entry.tags.length === 0) {
 94#KR:      entry.tags = ['日记'];
 95#VV:    }
 96#VH:    // 重新生成 emoji 字段（保证与 tags 同步）
 97#XW:    entry.emoji = entry.tags.map((tag) => getTagEmoji(tag)).join('');
 98#PW:  }
 99#VB:
100#PJ:  return entries;
101#TX:}
