103#NN:/** 获取文件 frontmatter（无则返回 null） */
104#KH:export function getFileFrontmatter(file: any): Record<string, any> | null {
105#YJ:  const cache = getApp().metadataCache.getFileCache(file);
106#PW:  return cache && cache.frontmatter ? cache.frontmatter : null;
107#MX:}
