109#KN:/** 文件创建时间 → { timeStr, timeValue } */
110#YK:export async function getFileTimeParts(file: any): Promise<{ timeStr: string; timeValue: number }> {
111#PH:  const stat = await file.stat;
112#KM:  const createTime = stat.ctime || stat.birthtime;
113#VX:  const m = moment(createTime);
114#WT:  return { timeStr: m.format('HH:mm'), timeValue: parseInt(m.format('HHmm')) };
115#TM:}
