135#XB:    let dateStr = fm['观影日期'];
136#KB:    if (!dateStr || !moment(dateStr, 'YYYY-MM-DD', true).isValid()) return null;
137#BH:    dateStr = moment(dateStr).format('YYYY-MM-DD');
138#NB:
139#PP:    let poster = fm['海报'];
140#PW:
141#BH:    // 文件创建时间作为时分秒
142#NN:    const { timeStr, timeValue } = await getFileTimeParts(file);
143#XP:
144#KQ:    // 解析标签
145#HP:    let rawTag = '';
146#TP:    if (fm.tags && Array.isArray(fm.tags) && fm.tags.length > 0) {
147#HR:      rawTag = fm.tags[0];
148#SK:    } else if (fm.tags && typeof fm.tags === 'string') {
149#ZV:      rawTag = fm.tags;
150#ZM:    }
151#ZZ:    let mainTag = '日记';
152#YP:    if (rawTag === '电影') mainTag = '电影';
153#BY:    else if (rawTag === '纪录片') mainTag = '纪录片';
154#YP:    else if (rawTag.endsWith('剧')) mainTag = '电视剧';
155#WQ:    else if (rawTag.endsWith('漫')) mainTag = '动漫';
156#MV:    else if (rawTag === '电视剧') mainTag = '电视剧';
157#NZ:    else if (rawTag === '动漫') mainTag = '动漫';
158#MK:
159#WP:    // 构建内容：影评 + 空行 + #《文件名》
160#YJ:    const fileNameWithoutExt = file.basename;
161#KK:    const content = `${review.trim()}\n\n![[${poster}]]\n\n#${fileNameWithoutExt}`;
162#YW:
163#BZ:    // 生成日记条目
