181#XP:/**
182#JH: * 解析信文件，生成一个日记条目（每个文件对应一个条目）
183#XW: */
184#XP:export async function parseLetterFile(file: any): Promise<DiaryEntry | null> {
185#QM:  try {
186#NP:    const fm = getFileFrontmatter(file);
187#PB:    if (!fm) return null;
188#PW:
189#KM:    // 如果 readonly 为 true，忽略
190#ZH:    if (fm.readonly === true) return null;
191#TK:
192#YM:    // 解析 date（支持 "YYYY-MM-DD" 或 "YYYY-MM-DD HH:mm"）
193#TB:    let dateStr = fm.date;
194#SB:    if (!dateStr) return null;
195#VR:
196#WT:    let parsed = moment(dateStr, ['YYYY-MM-DD', 'YYYY-MM-DD HH:mm'], true);
197#XN:    if (!parsed.isValid()) {
198#NK:      parsed = moment(dateStr);
199#NK:      if (!parsed.isValid()) return null;
200#VJ:    }
201#WJ:    const dateFormatted = parsed.format('YYYY-MM-DD');
202#RN:
203#QZ:    // 读取文件内容，提取正文（去掉 frontmatter）
204#WQ:    const fullContent = await getApp().vault.read(file);
205#KQ:    const frontmatterRegex = /^---\n([\s\S]*?)\n---\n/;
206#RM:    const match = fullContent.match(frontmatterRegex);
207#XP:    let body = fullContent;
208#ZV:    if (match) {
209#YZ:      body = fullContent.slice(match[0].length);
210#BY:    }
211#PJ:    body = body.trim();
212#JW:
213#YP:    // 标题（不含扩展名）
214#QQ:    const title = file.basename;
215#VM:    // 构建内容：标题（不带《》） + 空行 + 正文
216#YB:    const entryContent = `**${title}**\n\n${body}`.trim();
217#BQ:    // 文件创建时间作为时分秒
218#NN:    const { timeStr, timeValue } = await getFileTimeParts(file);
219#TX:
220#SJ:    return {
221#ZQ:      date: dateFormatted,
222#HN:      time: timeStr,
223#QH:      timeValue: timeValue,
224#JS:      tags: ['信'],
225#TV:      emoji: getTagEmoji('信'),
226#ZK:      content: entryContent,
227#ZB:      filename: file.path,
228#TY:      lineNumber: 0,
229#SH:      id: makeEntryId('letter', file, dateFormatted),
230#YT:    };
231#WQ:  } catch (err) {
232#QH:    console.error(`解析信文件失败 ${file.path}:`, err);
233#HP:    return null;
234#QR:  }
235#BQ:}
