239#HM:/** 解析自然语言日期时间；失败返回 null */
240#SQ:export function parseNaturalTime(input: string): any {
241#NB:  if (!input) return null;
242#NR:  const now = moment();
243#MH:  const lower = input.toLowerCase().trim();
244#XW:
245#VK:  const relMatch = lower.match(/^(\d+)\s*(分钟?|小时?|天|秒)前$/);
246#TV:  if (relMatch) {
247#RR:    const num = parseInt(relMatch[1], 10);
248#BJ:    const unit = relMatch[2];
249#YM:    if (unit.startsWith('分')) return now.clone().subtract(num, 'minutes');
250#YV:    if (unit.startsWith('小')) return now.clone().subtract(num, 'hours');
251#TR:    if (unit === '天') return now.clone().subtract(num, 'days');
252#RM:    if (unit === '秒') return now.clone().subtract(num, 'seconds');
253#JR:  }
254#NX:
255#BN:  const yesterdayMatch = lower.match(/^昨天\s*(\d{1,2}:\d{2})$/);
256#BN:  if (yesterdayMatch) {
257#YW:    const time = yesterdayMatch[1];
258#BX:    const yesterday = now.clone().subtract(1, 'days');
259#ZY:    return moment(`${yesterday.format('YYYY-MM-DD')} ${time}`, 'YYYY-MM-DD HH:mm', true);
260#YH:  }
261#MN:
262#HJ:  const beforeYesterdayMatch = lower.match(/^前天\s*(\d{1,2}:\d{2})$/);
263#TR:  if (beforeYesterdayMatch) {
264#RJ:    const time = beforeYesterdayMatch[1];
265#XT:    const before = now.clone().subtract(2, 'days');
266#YM:    return moment(`${before.format('YYYY-MM-DD')} ${time}`, 'YYYY-MM-DD HH:mm', true);
267#KR:  }
268#YY:
269#KR:  const std = moment(input, 'YYYY-MM-DD HH:mm', true);
270#BR:  if (std.isValid()) return std;
271#PT:  return null;
272#WZ:}

