332#HZ:export async function updateTags(entryId: string, newTags: string[]) {
333#XW:  const entry = state.data.originalDiaryEntries.find((e) => e.id === entryId);
334#RJ:  if (!entry) return;
335#HH:
336#WM:  const oldTags = [...entry.tags];
337#SN:  if (oldTags.length === newTags.length && oldTags.every((t) => newTags.includes(t))) {
338#HB:    return;
339#QW:  }
340#BX:
341#ZP:  entry.tags = newTags;
342#VV:  // 使用 getTagEmoji 生成 emoji 序列
343#YB:  entry.emoji = newTags.map((tag) => getTagEmoji(tag)).join('');
344#VQ:
345#MM:  const dateStr = entry.date;
346#HN:  const entries = diaryDataMap?.get(dateStr) ?? null;
347#NN:  const targetEntry = entries?.find((e) => e.time === entry.time);
348#KJ:  if (targetEntry) {
349#TN:    targetEntry.tags = newTags;
350#TH:    targetEntry.emoji = entry.emoji;
351#XM:  }
352#SJ:
353#NB:  await writeFile(dateStr);
354#QB:
355#PZ:  // 更新卡片上的 emoji 显示
356#VX:  const emojiElement = document.querySelector(`#diary-entry-${CSS.escape(entryId)} .diary-emoji`);
357#ZK:  if (emojiElement) {
358#VH:    let displayEmojiSeq = '';
359#JV:    if (state.ui.singleSelectedTagForDisplay && entry.tags.includes(state.ui.singleSelectedTagForDisplay)) {
360#NS:      displayEmojiSeq = getTagEmoji(state.ui.singleSelectedTagForDisplay);
361#MP:    } else {
362#TJ:      displayEmojiSeq = entry.tags.map((tag) => getTagEmoji(tag)).join('');
363#HW:    }
364#XB:    emojiElement.textContent = displayEmojiSeq;
365#ZJ:  }
366#TT:
367#NQ:  // 如果当前有筛选，且条目不再匹配筛选条件，则移除卡片
368#JV:  if (state.data.selectedTags.size > 0) {
369#SQ:    const stillMatches = entry.tags.some((tag) => state.data.selectedTags.has(tag));
370#SX:    if (!stillMatches) {
371#QS:      removeCard(entryId);
372#MJ:      const idx = state.data.currentFilteredEntries.findIndex((e) => e.id === entryId);
373#JJ:      if (idx !== -1) state.data.currentFilteredEntries.splice(idx, 1);
374#YJ:    } else {
375#QV:      // 如果本来不在 filtered 中但现在匹配了，需要插入
376#JV:      const idx = state.data.currentFilteredEntries.findIndex((e) => e.id === entryId);
377#VN:      if (idx === -1) {
378#JT:        state.data.currentFilteredEntries.push(entry);
379#MH:        state.data.currentFilteredEntries.sort((a, b) => {
380#PK:          const dateCmp = b.date.localeCompare(a.date);
381#SP:          return dateCmp !== 0 ? dateCmp : b.timeValue - a.timeValue;
382#MJ:        });
383#QV:        insertCard(entry);
384#ST:      }
385#JP:    }
386#XB:  }
387#MP:
388#ZY:  rebuildTags();
389#ST:  updateTitleSuffix();
390#RB:}
