602#ZK:      newEntry &&
603#WY:      (!selTagNames.length || newEntry.tags.some((tag) => selTagNames.includes(tag))) &&
604#ZR:      (!state.data.currentDateFilter ||
605#VY:        (state.data.currentDateFilter.month
606#MS:          ? newEntry.date.startsWith(`${state.data.currentDateFilter.year}-${state.data.currentDateFilter.month}`)
607#HP:          : newEntry.date.startsWith(state.data.currentDateFilter.year)))
608#YM:    ) {
