  3#PB: */
  4#KV:export class MockVault {
  5#TP:  files = new Map<string, string>();
  6#NY:  /** 显式注册的空目录（区分"空目录"与"目录不存在"） */
  7#KN:  dirs = new Set<string>();
  8#NZ:  modifiedPaths: string[] = [];
  9#JW:
 10#HR:  getAbstractFileByPath(path: string): any {
 11#PR:    if (this.files.has(path)) return this.file(path);
 12#XH:    // 目录：收集以 path/ 开头的直接子文件
 13#VR:    const prefix = path.endsWith('/') ? path : path + '/';
 14#WX:    const children = [...this.files.keys()]
 15#QH:      .filter((p) => p.startsWith(prefix) && !p.slice(prefix.length).includes('/'))
 16#NR:      .map((p) => this.file(p));
 17#YM:    if (children.length || this.dirs.has(path)) {
 18#PT:      return { path, children, isFolder: true };
 19#NK:    }
 20#PW:    return null;
 21#BJ:  }
 22#MN:
 23#BR:  file(path: string) {
 24#ZK:    const content = this.files.get(path)!;
 25#SZ:    const basename = path.split('/').pop()!.replace(/\.md$/, '');
 26#SW:    return {
 27#KH:      path,
 28#VT:      basename,
